// 自动生成例句与释义
function generateExampleAndMeaning(word, pos, meaning) {
    let en = '', cn = '';
    const p = (pos || '').toLowerCase();
    if (p.includes('v') || p.includes('vt') || p.includes('vi')) {
        en = `She decided to ${word} it.`;
        cn = `她决定${meaning}它。`;
    } else if (p.includes('n')) {
        en = `This is a good ${word}.`;
        cn = `这是一个好的${meaning}。`;
    } else if (p.includes('adj') || p.includes('a.')) {
        en = `It is very ${word}.`;
        cn = `它非常${meaning}。`;
    } else if (p.includes('adv') || p.includes('ad.')) {
        en = `He finished the task ${word}.`;
        cn = `他${meaning}地完成了任务。`;
    } else {
        en = `We need to learn the word "${word}".`;
        cn = `我们需要学习单词"${word}"，它的意思是${meaning}。`;
    }
    return { example: en, exampleMeaning: cn };
}

