// ============================================================
// 2. 动态生成：词汇集数据 + 核心练习库 + 拼写词库
// ============================================================

// 生成词汇集分类数据（带例句）
const VOCAB_COLLECTIONS = {};
for (const [sourceName, words] of Object.entries(RAW_VOCAB)) {
    VOCAB_COLLECTIONS[sourceName] = words.map(w => {
        const generated = generateExampleAndMeaning(w.w, w.p, w.m);
        return { word: w.w, pos: w.p, meaning: w.m, example: generated.example, exampleMeaning: generated.exampleMeaning };
    });
}
const VOCAB_SOURCES = Object.keys(VOCAB_COLLECTIONS);

// 自动合并去重，生成庞大的核心练习库（用于选择题）
const BASE_WORD_BANK = [];
const wordMap = new Map();
let idCounter = 1;

// 遍历 21 个附件
for (const sourceName in VOCAB_COLLECTIONS) {
    VOCAB_COLLECTIONS[sourceName].forEach(item => {
        const wordStr = item.word.trim();
        // 去重逻辑
        if (!wordMap.has(wordStr)) {
            wordMap.set(wordStr, {
                id: idCounter++,
                word: wordStr,
                pos: item.pos,
                meaning: item.meaning,
                example: item.example,
                exampleMeaning: item.exampleMeaning
            });
        }
    });
}

// 转换成数组
wordMap.forEach(item => BASE_WORD_BANK.push(item));


// ============================================================
// 3. 错题集本地存储操作
// ============================================================
const STORAGE_KEY = 'word_app_wrong_set';
function loadWrongSet() {
    try {
        const stored = localStorage.getItem(STORAGE_KEY);
        if (stored) return new Set(JSON.parse(stored));
    } catch (e) { console.warn(e); }
    return new Set();
}
let wrongSet = loadWrongSet();

function saveWrongSet() {
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(Array.from(wrongSet))); } catch (e) { console.warn(e); }
}

// ============================================================
// 4. 通用方法 (打乱数组、发音等)
// ============================================================
function shuffleArray(arr) {
    for (let i = arr.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
}

function speakWord(word) {
    if (!window.speechSynthesis) return alert('您的浏览器不支持语音播放');
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(word);
    utterance.lang = 'en-US'; utterance.rate = 0.85;
    window.speechSynthesis.speak(utterance);
}

// 过滤出纯字母单词，供拼写模块和拼写练习使用
const ALL_VOCAB_WORDS_MAP = new Map();
const isValidWord = (w) => /^[a-zA-Z\-']+$/.test(w); // 允许字母、连字符和单引号

BASE_WORD_BANK.forEach(item => {
    if (isValidWord(item.word)) {
        ALL_VOCAB_WORDS_MAP.set(item.word, item);
    }
});

const ALL_VOCAB_WORDS = Array.from(ALL_VOCAB_WORDS_MAP.values());